fn solve(m: i8, d: i8) -> i8 {
    let days_in_month: i8 = match m {
        1 => 31,
        2 => 28,
        3 => 31,
        4 => 30,
        5 => 31,
        6 => 30,
        7 => 31,
        8 => 31,
        9 => 30,
        10 => 31,
        11 => 30,
        12 => 31,
        _ => unreachable!("month must be in 1..=12"),
    };

    // weeks = 1 + floor((d-1 + days-1)/7) = 1 + floor((d + days - 2)/7)
    1 + (d + days_in_month - 2) / 7
}